-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.102.0',
  '2026-09-23',
  'Настройки: уведомления бота в одном месте и выгрузка данных',
  E'Новый раздел «Уведомления от бота». Раньше рассылки были разбросаны по страницам, а общего выключателя не было вовсе — теперь семь переключателей: напоминания, чек-листы, задачи, платежи, серверы, автоматизация, почта и чеки.\n\nТам же тихие часы: с 23:00 до 8:00 (или как поставите) бот молчит. Сообщения при этом не пропадают — накопленное придёт, когда тихие часы закончатся. Время берётся по часам вашего устройства. Ответы на ваши же действия — то, что вы отправляете кнопкой «в бот», — приходят всегда: глушить то, что человек только что попросил, неправильно.\n\nВторой новый раздел — «Мои данные». «Выгрузить мои данные» сохраняет файл со всеми вашими записями: трекер, чек-листы, дневник, задачи, ссылки, финансы и остальное. Рядом — удаление аккаунта: стираются все записи во всех разделах, поэтому подтверждение не кнопкой, а словом «УДАЛИТЬ», вписанным руками.',
  E'Уведомления. Миграция 0144: user_settings.notify_prefs (JSONB — виды знает приложение, новая рассылка не должна требовать миграции) и таблица notify_queue с частичным индексом по send_after. store.NotifyPrefs хранит выключенные виды (по умолчанию включено всё), окно тишины в минутах местного времени и смещение часового пояса; QuietUntil считает конец тишины с переходом через полночь (есть тест на пять моментов суток).\n\nnotify.Bot получил SendKind(kind) и хук Deliver: логика с настройками живёт в cmd/server, бот остаётся отправлялкой без доступа к базе. Выключенный вид отбрасывается, тихие часы кладут сообщение в notify_queue до конца окна, notifyqueue.Worker раз в минуту досылает наступившие (SendMessage напрямую — иначе сообщение ходило бы по кругу). Ошибка чтения настроек или записи в очередь = слать сейчас: потерять уведомление хуже, чем прислать не вовремя. На SendKind переведены reminders, checkerreset, tasksnotify, financenotify, servers, automation, receiptimport и smtpd; ручки httpapi и tgphotos остались на SendMessage — это ответы на действия человека.\n\nВыгрузка. store.ExportUserData не содержит списка таблиц: сначала берутся все таблицы с колонкой user_id (information_schema), потом в три прохода — связанные с ними внешними ключами (tracker_marks через tracker_categories и так далее), плюс своя строка из users. Условия склеиваются из имён, экранированных pgx.Identifier; access_tokens и notify_queue пропускаются. Пустые таблицы в файл не попадают. Удаление аккаунта — DELETE FROM users (почти все таблицы объявлены ON DELETE CASCADE) плюс файлы фонов с диска; POST, а не DELETE: тело с подтверждением у DELETE поддерживают не все прокси.\n\nПроверено на живом сервере: напоминание в тихие часы легло в очередь и было доставлено воркером после сдвига срока; при выключенном виде «Напоминания» оно отработало и не прислало ничего; выгрузка на отдельном пользователе вернула 7 таблиц вместе с дочерними отметками трекера и строкой users; удаление приняло только точное слово и унесло каскадом задачи и отметки.'
);
-- +goose StatementEnd

